  "stuSess.creditAppliedSuccess": "أُضيف €{amount} إلى رصيدك وسيُستخدم تلقائيًا للدرس التالي.",
  "stuSess.refundContactNote": "لاسترداد المبلغ، يرجى التواصل مع <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a>.",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">هل لديك أسئلة أو تواجه مشكلة؟ تواصل مع <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a>.</p><p class=\"font-semibold text-emerald-900\">بدأت عملية استرداد المبلغ عبر Stripe.</p><p class=\"text-emerald-800 mt-1\">تصل المبالغ المستردة إلى البطاقة عادةً خلال نحو <strong>5–10 أيام عمل</strong> (قد تختلف المدة باختلاف البنك). إذا لم تستلم المبلغ خلال المدة المعتادة، راسل <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a>.</p>",
  "stuSess.refundSuccessManualTutor": "<p>يبدو أن هذا الدرس لم يُدفع عبر Stripe على Tutlio (مثل الدفع بتحويل بنكي أو نقدًا). لا تتوفر هنا عملية استرداد تلقائية.</p><p class=\"mt-2\">لترتيب استرداد المبلغ، تواصل مع مدرّسك <strong>{tutor}</strong> — باستخدام البريد الإلكتروني أو بيانات الاتصال في حجوزاتك أو التي يزوّدك بها المدرّس مباشرةً.</p>",
  "stuSess.refundSuccessManualOrg": "<p>يبدو أن هذا الدرس لم يُدفع عبر Stripe على Tutlio (مثل الدفع بتحويل بنكي أو نقدًا). لا تتوفر هنا عملية استرداد تلقائية.</p><p class=\"mt-2\">بما أنك تتعلّم من خلال مؤسسة، تواصل مع <strong>مسؤول المؤسسة</strong> (عبر مدرّسك أو بيانات الاتصال المنشورة للمؤسسة).</p>",
  "stuSess.refundTutorFallback": "مدرّسك",
