  "feature.calendar.faq.howBookQ": "كيف يحجز الطلاب الدروس؟",
  "feature.calendar.faq.howBookA": "يتلقى الطلاب رابط حجز شخصيًا يمكنهم من خلاله رؤية فتراتك المتاحة والحجز مباشرةً. تتحكم أنت في الأوقات المتاحة والمدة المسموح بها للحجز المسبق.",
  "feature.calendar.faq.groupLessonsQ": "هل يمكنني جدولة دروس جماعية؟",
  "feature.calendar.faq.groupLessonsA": "نعم! يمكنك إنشاء فترات لدروس جماعية يسجّل فيها عدة طلاب في الموعد نفسه.",
  "feature.calendar.faq.mobileCalendarQ": "هل يعمل التقويم على الهاتف؟",
  "feature.calendar.faq.mobileCalendarA": "نعم، يعمل Tutlio على أي جهاز — الحاسوب أو الجهاز اللوحي أو الهاتف. يمكنك أيضًا تثبيته كتطبيق ويب تقدّمي للوصول السريع.",
  "feature.waitlist.pageTitle": "قائمة انتظار الطلاب — لا تخسر الإيرادات بسبب الإلغاء",
  "feature.waitlist.pageDesc": "عندما يُلغي طالب درسًا، يعرض Tutlio الموعد المتاح تلقائيًا على الطلاب في قائمة الانتظار. املأ الفترات الشاغرة فورًا وحافظ على جدول مكتمل الحجوزات.",
  "feature.waitlist.detailsTitle": "كيف تعمل قائمة الانتظار",
  "feature.waitlist.autoFill": "ملء المواعيد تلقائيًا",
  "feature.waitlist.autoFillDesc": "عند إلغاء درس، يُبلّغ النظام فورًا الطلاب في قائمة الانتظار المهتمين بهذا الموعد — ويحصل أول من يؤكد على المكان.",
  "feature.waitlist.notifications": "إشعارات فورية",
