  "feature.waitlist.revenue": "حماية الإيرادات",
  "feature.waitlist.revenueDesc": "توقّف عن خسارة الدخل بسبب الإلغاء. تضمن قائمة الانتظار ملء المواعيد المتاحة بسرعة للاستفادة القصوى من ساعات التدريس.",
  "feature.waitlist.faq.howWorksQ": "كيف تملأ قائمة الانتظار المواعيد المُلغاة؟",
  "feature.waitlist.faq.howWorksA": "عندما يُلغي طالب درسًا، يتحقق النظام من الطلاب المسجّلين في قائمة الانتظار لهذا الموعد ويرسل إليهم عرضًا. يحصل أول طالب يؤكد على الدرس.",
