  "feature.waitlist.faq.automaticQ": "هل تعمل قائمة الانتظار تلقائيًا بالكامل؟",
  "feature.waitlist.faq.automaticA": "نعم! بعد الإعداد، تعمل جميع الخطوات تلقائيًا — من الإلغاء إلى الإشعار ثم إعادة الحجز. لا يلزمك فعل أي شيء.",
  "feature.payments.pageTitle": "معالجة مدفوعات المدرّسين والفوترة",
