  "feature.payments.packagesDesc": "بِع باقات دروس (مثلًا: 10 دروس بسعر مخفّض) وتابع استخدامها تلقائيًا.",
  "feature.payments.faq.methodsQ": "ما وسائل الدفع المدعومة؟",
