  "orgTutorPolicy.s1Body": "تنظّم هذه القواعد استخدامك لمنصة Tutlio («المنصة») بوصفك معلّمًا أو مدرّسًا خصوصيًا («المدرّس»). دعتك إلى استخدام المنصة الجهة التعليمية أو المدرسة أو مركز الدروس الخصوصية الذي تمثّله («المؤسسة»). تتولّى MB Tutlio الصيانة والدعم التقني للمنصة. باستخدام حسابك، فإنك توافق على هذه القواعد وسياسة الخصوصية.",
  "orgTutorPolicy.s2Title": "2. إدارة الحساب والجداول",
  "orgTutorPolicy.s2Intro": "صُممت المنصة لتجنّب إهدار وقتك في تنسيق مواعيد الدروس مع الطلاب.",
  "orgTutorPolicy.s2Link": "رابط فريد: يُخصّص لك رابط شخصي لحجز الدروس (بناءً على المواد التي تدرّسها) يستخدمه الطلاب لجدولة الدروس.",
  "orgTutorPolicy.s2Calendar": "مزامنة التقويم: تعتمد أوقاتك المتاحة مباشرةً على تكامل تقويم Google (مزامنة في 2 اتجاه). تتحمل شخصيًا مسؤولية دقة الأوقات المتاحة الظاهرة في تقويمك وتحديثها. لن تسمح المنصة للطلاب بحجز الأوقات المحددة بوصفها مشغولة في تقويمك.",
  "orgTutorPolicy.s2Security": "أمان الحساب: حسابك شخصي. يجب الحفاظ على أمان بيانات تسجيل الدخول وعدم مشاركتها مع أطراف ثالثة.",
  "orgTutorPolicy.s3Title": "3. إلغاء الدروس وقائمة الانتظار",
  "orgTutorPolicy.s3Intro": "تساعد المنصة على الاستفادة القصوى من جدولك وتجنّب الفترات الشاغرة:",
  "orgTutorPolicy.s3Auto": "إذا ألغى طالب درسًا، ترسل المنصة تلقائيًا إشعارًا (برسالة نصية/بالبريد الإلكتروني) إلى الطلاب الآخرين في قائمة انتظارك، وتعرض عليهم الموعد الذي أصبح متاحًا. لا يلزمك أي إجراء إضافي.",
  "orgTutorPolicy.s3Rules": "تحدّد مؤسستك قواعد إلغاء الدروس (المدة المطلوبة للإلغاء المسبق والنتائج المترتبة عليه).",
  "orgTutorPolicy.s4Title": "4. الشؤون المالية والمدفوعات",
  "orgTutorPolicy.s4Intro": "لا تحتاج إلى القلق بشأن الفوترة أو تحصيل المدفوعات من أولياء الأمور:",
  "orgTutorPolicy.s4Advance": "تُحصّل جميع مدفوعات الطلاب (أو أولياء الأمور) مقابل دروسك مقدمًا عبر المنصة وتُحوّل مباشرةً إلى مؤسستك.",
  "orgTutorPolicy.s4Confirmed": "تقدّم الدرس فقط عندما يكون مؤكدًا في النظام (أي تم تحصيل رسومه بالفعل).",
  "orgTutorPolicy.s4Contact": "للاستفسار عن راتبك ومواعيد صرف المستحقات والمسائل المالية الأخرى، يرجى التواصل مباشرةً مع مسؤول مؤسستك. لا تُجري MB Tutlio أي معاملات مالية مباشرة مع المدرّسين.",
  "orgTutorPolicy.s5Title": "5. حماية بيانات الطلاب (GDPR)",
  "orgTutorPolicy.s5Intro": "بوصفك مدرّسًا، يمكنك الوصول إلى بيانات الطلاب الشخصية والملاحظات الداخلية والمواد التعليمية. وتلتزم بما يلي:",
  "orgTutorPolicy.s5Use": "استخدام هذه البيانات حصريًا لتنظيم الدروس وتقديمها.",
  "orgTutorPolicy.s5NoCopy": "عدم نسخ بيانات اتصال الطلاب أو أولياء الأمور أو تصديرها أو توزيعها خارج المنصة.",
  "orgTutorPolicy.s5Notes": "حماية سجلات المؤسسة الداخلية (الملاحظات حول تقدّم الطلاب) التي لا يطّلع عليها إلا أنت وإدارة المؤسسة، دون الطلاب أو أولياء الأمور.",
  "orgTutorPolicy.s5Termination": "عند انتهاء علاقة عملك بالمؤسسة، تُلغى صلاحية وصولك إلى هذه البيانات فورًا.",
  "orgTutorPolicy.s6Title": "6. التشغيل التقني وحدود المسؤولية",
  "orgTutorPolicy.s6Body": "يُحظر استخدام المنصة لأغراض غير قانونية أو توزيع روابط ضارة في مواد الدروس أو تعطيل النظام بأي طريقة أخرى. تضمن MB Tutlio تشغيل المنصة وصيانتها التقنية، لكنها لا تتحمل مسؤولية الأعطال الناتجة عن اتصالك بالإنترنت أو أعطال أجهزتك أو إعدادات تقويم Google غير الصحيحة.",
  "orgTutorPolicy.s7Title": "7. الدعم والتواصل",
  "orgTutorPolicy.s7Org": "للأسئلة المتعلقة بجداول الدروس أو الرواتب أو توزيع الطلاب أو تنظيم العمل، تواصل مع مسؤول مؤسستك.",
  "orgTutorPolicy.s7Tech": "عند حدوث أخطاء تقنية في المنصة (مثل تعطل مزامنة التقويم أو عدم تلقي الإشعارات)، أبلغ مسؤول مؤسستك، الذي سيتواصل مع فريق الدعم التقني في Tutlio.",
